@startuml

class WebPortal {
  + version_number : string
  + url_address : string
}

class Building {
  + id : string
  + name : string
  + energy_class : string
  + address : string
  + year_of_construction : int
}

class AdditionalEntry {
  + name : string
  + is_public : boolean
}

abstract class EntryValue {}

class TextualInformation extends EntryValue {}

class NumericalInformation extends EntryValue {
  + value : float
  + unit : string
}

class Image {
  + file_name : string
}

class User {
  + username : string
  + email : string
  + password : string
}

class Administrator extends User {
  + id_card_number : string
}

class Comment {
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "1" -- "*" User : has
WebPortal "1" -- "*" Visitor : has
Visitor "0..1" -- "1" User : registers as

Building "1" *-- "*" AdditionalEntry
Building "1" *-- "*" Image
Building "1" -- "1" Image : profile photo
Building "1" -- "*" Comment : has

User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
User "1" -- "*" AdditionalEntry : manages

AdditionalEntry "1" -- "1" EntryValue

@enduml

